"""art.library.index: the LIBRARY list and its atlas constants (library.ts), described: generated data, ported as a table only."""
from fractal.holon import Fn, Holon

HOLON = Holon(
    id="art.library.index", rung=3, title="Library index",
    purpose="The one list of pictures: the Maple Falls town art first, then each folder's appended rows.",
    requires=[
        "ATLAS_SIZE is 2048 and ATLAS_MIP0 is 0.6 (library.ts lines 130 and 131).",
        "The file is generated by scripts/assets/prep-sprites.mjs; the appended folders follow its rows (library.ts header).",
    ],
    owns=["LIBRARY (LibItem[])", "ATLAS_PAGES (the page URLs, five mips each)", "the walker, spectator, golfer and animal base indices"],
    files=["src/game/library.ts", "src/game/ground-art.ts", "src/game/types.ts"],
    dynamics=[
        Fn(name="LIBRARY", at="src/game/library.ts:132", does="the list of every library picture (the saved index is its position)", sig="LIBRARY: LibItem[]"),
        Fn(name="ATLAS_PAGES", at="src/game/library.ts:129", does="the atlas page URLs by page and mip", sig="ATLAS_PAGES: string[][]"),
    ],
    inputs=["the generated rows (prep-sprites.mjs output)", "the appended folder libraries"],
    outputs=["LIBRARY for every system that draws a sprite"],
    tests=["tests/kit.test.ts", "tests/newart.test.ts", "tests/atlas-pages.test.ts", "tests/props-all.test.ts"],
    below=[], above=["art.library.vehicles", "art.library.buildings", "art.library.plants", "art.library.views", "render.sprites.pack"],
    dual="MISSING: a library row cannot be removed at runtime (saved indices point at it; object-eight-library.ts keeps its rows append-only)",
    rules=["new art used everywhere"],
    impl="describe",
)
